// Unit dashboard, generation phases: R6 start, R9 live progress, R11 retry/cancel/regenerate,
// R12 spend guard. Mockups: docs/design/lesson-authoring/R12-start-generation.html,
// R9-dashboard-generating.html, R11-cancel-run.html, R11-row-actions.html,
// R11-regenerate-confirm.html and R12-dashboard-spend-cap.html. Decisions: D-024, D-026, D-027.
//
// Runs started from the UI are generated by the e2e server's worker with the fake LLM
// (tests/e2e/fake_llm.ts); no test calls a model provider. Other states are written to the
// database the way the worker writes them, NOTIFY included (dashboard_support.ts).
//
// Names the mockups don't draw, chosen here: the admin's "Raise cap..." button opens a dialog
// with a "Spend cap for this run" field and a "Save cap" button; the start dialog shows
// "Concurrency" as a read-only term (D-024 (3)).
import { FAIL_MARKER, FAKE_LLM_ERROR, generatedTitle } from './fake_llm'
import {
  ADMIN,
  DashboardDb,
  GENERATING_ERROR,
  LESSON_COST_USD,
  LIVE_UPDATE_MS,
  STOPPED_RUN,
  expect,
  expectSameDocument,
  lessonRow,
  markDocument,
  openUnit,
  range,
  seedGeneratingState,
  seedReviewState,
  seedSpendCapState,
  seededTitle,
  termValue,
  test,
  tile,
  usd,
  type SampleUnit,
} from './dashboard_support'
import { expectNoAxeViolations, signIn, snap } from './support'

const IN_BACKGROUND =
  'Lessons are generated in the background. You can close the browser; the run keeps going.'
const FLEX_NOTE = "Flex days aren't included. Generate a flex day from its row when you need one."
const ESTIMATE_NOTE =
  'The estimate is the number of lessons times the expected cost of one lesson on this model. If the run reaches the cap, no new lessons start and finished ones are kept.'
const PROGRESS_NOTE =
  'Lessons open as soon as they finish. You can close this page; generation keeps going.'
const CANCEL_TEXT =
  "The 20 queued lessons won't start, and the 4 lessons being generated stop. The 15 generated lessons are kept. You can generate the rest later."
const NOT_STARTED = 'Not started: the spend cap stopped the run.'

/** Generous wait for the fake worker (1 s per call, 4 at a time) to get through a run. */
const RUN_MS = 90_000

function progress(page: import('@playwright/test').Page) {
  return page.getByRole('region', { name: 'Generation progress' })
}

async function waitForJobs(
  dash: DashboardDb,
  unit: SampleUnit,
  lessons: number[],
  status: string,
): Promise<void> {
  await expect
    .poll(
      async () => {
        const statuses = await dash.jobStatuses(unit)
        return lessons.filter((n) => statuses.get(n) !== status)
      },
      { timeout: RUN_MS },
    )
    .toEqual([])
}

test.describe('Unit dashboard: before generation (R6, R12)', () => {
  test('shows 0 of 41 generated and every tile as Not generated', async ({ page, dash }) => {
    const unit = await dash.importSampleUnit()
    await signIn(page)
    await openUnit(page, unit)

    const summary = page.getByRole('region', { name: 'Generation' })
    await expect(summary).toContainText('0 of 41 generated')
    await expect(summary).toContainText(
      'Nothing has been generated yet. Review the prompt, then start generation.',
    )
    await expect(page.getByRole('img', { name: /^Lesson \d+, Not generated$/ })).toHaveCount(41)
    await expect(page.getByRole('link', { name: 'Edit prompt' })).toBeVisible()
    await expect(page.getByRole('button', { name: 'Generate lessons...' })).toBeVisible()
    await expect(termValue(page, 'Prompt')).toHaveText('v1')
    await expect(termValue(page, 'Model')).toHaveText('Haiku-class')
    await expect(termValue(page, 'Spend cap')).toHaveText('$5.00')
  })

  test('the start dialog shows the scope, model, prompt, a real cost estimate, the cap and read-only concurrency', async ({
    page,
    dash,
  }, testInfo) => {
    const unit = await dash.importSampleUnit()
    await signIn(page)
    await openUnit(page, unit)
    const trigger = page.getByRole('button', { name: 'Generate lessons...' })
    await trigger.click()

    const dialog = page.getByRole('dialog', { name: 'Generate lessons' })
    await expect(dialog).toBeVisible()
    await expect(dialog).toContainText(IN_BACKGROUND)
    await expect(dialog.getByRole('radio', { name: 'All 41 numbered lessons' })).toBeChecked()
    await expect(dialog.getByRole('radio', { name: 'Selected lessons' })).not.toBeChecked()
    await expect(dialog).toContainText(FLEX_NOTE)
    await expect(dialog.getByLabel('Model')).toContainText('Haiku-class (low cost, default)')
    await expect(dialog).toContainText('v1')
    await expect(dialog.getByRole('link', { name: 'View prompt' })).toBeVisible()

    // No measured lessons yet: 41 x the per-lesson estimate on the Haiku-class model (D-024 (2)).
    await expect(termValue(dialog, 'Estimated cost for 41 lessons')).toHaveText(
      usd(41 * LESSON_COST_USD),
    )
    await expect(termValue(dialog, 'Spend cap for this run')).toHaveText('$5.00')
    await expect(dialog).toContainText(ESTIMATE_NOTE)
    await expect(dialog).not.toContainText('{{')

    // D-024 (3): concurrency is shown from the environment and can't be edited here.
    await expect(termValue(dialog, 'Concurrency')).toContainText('4')
    await expect(dialog.getByRole('spinbutton')).toHaveCount(0)
    await expect(dialog.getByLabel(/concurrency/i)).toHaveCount(0)

    await expect(dialog.getByRole('button', { name: 'Cancel' })).toBeFocused()
    await expect(dialog.getByRole('button', { name: 'Start generation' })).toBeEnabled()
    await snap(page, testInfo, 'R12-start-generation')
    await expectNoAxeViolations(page)

    await page.keyboard.press('Escape')
    await expect(dialog).toBeHidden()
    await expect(trigger).toBeFocused()
    expect(await dash.runs(unit.unitId)).toEqual([])
  })

  test('Start generation queues the 41 numbered lessons and the page follows the run live until it finishes', async ({
    page,
    dash,
  }) => {
    test.setTimeout(150_000)
    const unit = await dash.importSampleUnit()
    await dash.setLesson(unit, 9, { textDependentQuestion: `${FAIL_MARKER} lesson 9?` })
    await signIn(page)
    await openUnit(page, unit)
    await markDocument(page)

    await page.getByRole('button', { name: 'Generate lessons...' }).click()
    await page
      .getByRole('dialog', { name: 'Generate lessons' })
      .getByRole('button', { name: 'Start generation' })
      .click()
    await expect(page.getByRole('dialog', { name: 'Generate lessons' })).toBeHidden()

    const runs = await dash.runs(unit.unitId)
    expect(runs).toHaveLength(1)
    expect(runs[0]).toMatchObject({ model: 'claude-haiku-5-5', capUsd: 5 })
    const queued = await dash.jobStatuses(unit)
    expect([...queued.keys()].sort((a, b) => a - b)).toEqual(range(1, 41))

    await expect(progress(page)).toHaveAttribute('aria-live', 'polite')
    await expect(progress(page)).toContainText('Running')
    await expect(page.getByRole('button', { name: 'Cancel run' })).toBeVisible()

    // R9: lessons open as soon as they finish, while the rest are still running.
    await expect(lessonRow(page, 1).getByRole('link', { name: generatedTitle(1) })).toBeVisible({
      timeout: RUN_MS,
    })

    await expect(tile(page, 41, 'Draft')).toBeVisible({ timeout: RUN_MS })
    await expect(tile(page, 9, 'Failed')).toBeVisible({ timeout: RUN_MS })
    await expect(lessonRow(page, 9)).toContainText(FAKE_LLM_ERROR)
    await expect(lessonRow(page, 9).getByRole('button', { name: 'Retry' })).toBeVisible()

    // The finished run: the summary moves to review and keeps the run's real cost (R12).
    await expect(page.getByText('0 of 41 approved')).toBeVisible({ timeout: RUN_MS })
    await expect(page.getByText(/Generation finished at .+ with prompt v1\./)).toBeVisible()
    await expect(page.getByText(`Run cost ${usd(40 * LESSON_COST_USD)}.`)).toBeVisible()

    // D-024 (7): the generated title, with the outline line as secondary text.
    const row4 = lessonRow(page, 4)
    await expect(row4.getByRole('link', { name: generatedTitle(4) })).toBeVisible()
    await expect(row4).toContainText(unit.outlineLines.get(4)!)
    await expectSameDocument(page)
  })

  test('a reviewer sees the progress but can neither start generation nor edit the prompt', async ({
    page,
    dash,
  }) => {
    const unit = await dash.importSampleUnit()
    await signIn(page, 'reviewer01@example.com')
    await openUnit(page, unit)
    await expect(page.getByRole('region', { name: 'Generation' })).toContainText(
      '0 of 41 generated',
    )
    await expect(page.getByRole('button', { name: 'Generate lessons...' })).toHaveCount(0)
    await expect(page.getByRole('link', { name: 'Edit prompt' })).toHaveCount(0)
  })
})

test.describe('Unit dashboard: generating (R9, R11, R12)', () => {
  test('shows counts, tiles, running cost and failed rows with the error and Retry', async ({
    page,
    dash,
  }, testInfo) => {
    const unit = await dash.importSampleUnit()
    await seedGeneratingState(dash, unit)
    await signIn(page)
    await openUnit(page, unit)

    await expect(progress(page)).toHaveAttribute('aria-live', 'polite')
    await expect(progress(page)).toContainText('15 of 41 generated')
    await expect(progress(page)).toContainText('Running')
    await expect(progress(page)).toContainText(
      `4 generating, 20 queued, 2 failed. ${PROGRESS_NOTE}`,
    )
    await expect(tile(page, 1, 'Draft')).toBeVisible()
    await expect(tile(page, 9, 'Failed')).toBeVisible()
    await expect(tile(page, 18, 'Generating')).toBeVisible()
    await expect(tile(page, 41, 'Queued')).toBeVisible()

    // D-027: real dollar values, never the mockup's placeholders.
    await expect(termValue(page, 'Running cost')).toHaveText(usd(17 * LESSON_COST_USD))
    await expect(termValue(page, 'Estimate for run')).toHaveText(usd(41 * LESSON_COST_USD))
    await expect(termValue(page, 'Spend cap')).toHaveText('$5.00')
    await expect(termValue(page, 'Model')).toHaveText('Haiku-class')
    await expect(termValue(page, 'Prompt')).toHaveText('v1')
    await expect(termValue(page, 'Started')).toContainText('Author 01')
    await expect(page.locator('body')).not.toContainText('{{')
    await expect(page.getByRole('button', { name: 'Retry 2 failed' })).toBeVisible()
    await expect(page.getByRole('button', { name: 'Cancel run' })).toBeVisible()

    for (const n of [9, 14]) {
      await expect(lessonRow(page, n)).toContainText(GENERATING_ERROR)
      await expect(lessonRow(page, n).getByRole('button', { name: 'Retry' })).toBeVisible()
    }
    // A generated lesson opens straight away: its (generated) title is the link.
    await expect(lessonRow(page, 4).getByRole('link', { name: seededTitle(4) })).toBeVisible()
    await snap(page, testInfo, 'R9-dashboard-generating')
    await expectNoAxeViolations(page)
  })

  test('status changes show without a reload within 5 seconds', async ({ page, dash }) => {
    const unit = await dash.importSampleUnit()
    const runId = await seedGeneratingState(dash, unit)
    await signIn(page)
    await openUnit(page, unit)
    await expect(progress(page)).toContainText('15 of 41 generated')
    await markDocument(page)
    const live = { timeout: LIVE_UPDATE_MS }

    await dash.setJob(unit, runId, 22, 'generating')
    await expect(tile(page, 22, 'Generating')).toBeVisible(live)
    await expect(progress(page)).toContainText('5 generating, 19 queued, 2 failed', live)

    await dash.setRun(runId, { costUsd: 18 * LESSON_COST_USD })
    await dash.setJob(unit, runId, 18, 'generated')
    await expect(tile(page, 18, 'Draft')).toBeVisible(live)
    await expect(progress(page)).toContainText('16 of 41 generated', live)
    await expect(lessonRow(page, 18).getByRole('link', { name: seededTitle(18) })).toBeVisible(live)
    await expect(termValue(page, 'Running cost')).toHaveText(usd(18 * LESSON_COST_USD), live)

    await dash.setJob(unit, runId, 19, 'failed', { error: 'Model call failed: overloaded' })
    await expect(tile(page, 19, 'Failed')).toBeVisible(live)
    await expect(lessonRow(page, 19)).toContainText('Model call failed: overloaded', live)
    await expect(lessonRow(page, 19).getByRole('button', { name: 'Retry' })).toBeVisible(live)
    await expect(page.getByRole('button', { name: 'Retry 3 failed' })).toBeVisible(live)
    await expectSameDocument(page)
  })

  test('Cancel run asks first, then stops the queued lessons and keeps the generated ones', async ({
    page,
    dash,
  }, testInfo) => {
    const unit = await dash.importSampleUnit()
    const runId = await seedGeneratingState(dash, unit)
    await signIn(page)
    await openUnit(page, unit)

    const trigger = page.getByRole('button', { name: 'Cancel run' })
    await trigger.click()
    const dialog = page.getByRole('alertdialog', { name: 'Cancel this run?' })
    await expect(dialog).toContainText(CANCEL_TEXT)
    await expect(dialog.getByRole('button', { name: 'Keep running' })).toBeFocused()
    await snap(page, testInfo, 'R11-cancel-run')

    await dialog.getByRole('button', { name: 'Keep running' }).click()
    await expect(dialog).toBeHidden()
    await expect(trigger).toBeFocused()
    expect((await dash.runs(unit.unitId))[0]!.status).toBe('running')

    await trigger.click()
    await dialog.getByRole('button', { name: 'Cancel run' }).click()
    await expect(dialog).toBeHidden()
    await expect.poll(async () => (await dash.runs(unit.unitId))[0]!.status).toBe('cancelled')
    const statuses = await dash.jobStatuses(unit)
    expect(range(22, 41).map((n) => statuses.get(n))).toEqual(range(22, 41).map(() => 'cancelled'))
    expect(statuses.get(1)).toBe('generated')
    expect(runId).toBe((await dash.runs(unit.unitId))[0]!.id)

    await expect(progress(page)).not.toContainText('Running', { timeout: LIVE_UPDATE_MS })
    await expect(page.getByRole('button', { name: 'Cancel run' })).toHaveCount(0)
    await expect(tile(page, 1, 'Draft')).toBeVisible()
    await expect(tile(page, 22, 'Queued')).toHaveCount(0)
  })
})

test.describe('Unit dashboard: retry failed lessons (R6, R11)', () => {
  test('Retry on a row regenerates that lesson only; "Retry N failed" regenerates the rest', async ({
    page,
    dash,
  }) => {
    test.setTimeout(240_000)
    const unit = await dash.importSampleUnit()
    for (const n of [9, 14]) {
      await dash.setLesson(unit, n, { textDependentQuestion: `${FAIL_MARKER} lesson ${n}?` })
    }
    await signIn(page)
    await openUnit(page, unit)
    await page.getByRole('button', { name: 'Generate lessons...' }).click()
    await page.getByRole('button', { name: 'Start generation' }).click()
    await waitForJobs(dash, unit, [9, 14], 'failed')
    await expect(page.getByText('0 of 41 approved')).toBeVisible({ timeout: RUN_MS })

    await expect(tile(page, 9, 'Failed')).toBeVisible()
    await expect(tile(page, 14, 'Failed')).toBeVisible()
    await expect(lessonRow(page, 14)).toContainText(FAKE_LLM_ERROR)
    await expect(page.getByRole('button', { name: 'Retry 2 failed' })).toBeVisible()

    // The model stops failing for both lessons; retry lesson 9 alone first.
    for (const n of [9, 14]) {
      await dash.setLesson(unit, n, { textDependentQuestion: `Question for lesson ${n}?` })
    }
    await lessonRow(page, 9).getByRole('button', { name: 'Retry' }).click()
    await expect(tile(page, 9, 'Draft')).toBeVisible({ timeout: RUN_MS })
    await expect(lessonRow(page, 9).getByRole('link', { name: generatedTitle(9) })).toBeVisible()
    await expect(tile(page, 14, 'Failed')).toBeVisible()
    await expect(page.getByRole('button', { name: 'Retry 1 failed' })).toBeVisible()

    await page.getByRole('button', { name: 'Retry 1 failed' }).click()
    await expect(tile(page, 14, 'Draft')).toBeVisible({ timeout: RUN_MS })
    await expect(page.getByRole('button', { name: /^Retry \d+ failed$/ })).toHaveCount(0)
    // Only the failed lessons were sent again: 41 first jobs plus the two retries.
    const runs = await dash.runs(unit.unitId)
    expect(runs.length).toBeGreaterThanOrEqual(2)
  })
})

test.describe('Unit dashboard: stopped by the spend cap (R12, D-024)', () => {
  test('shows "Stopped: spend cap reached", the counts and the rows that never started', async ({
    page,
    dash,
  }, testInfo) => {
    const unit = await dash.importSampleUnit()
    await seedSpendCapState(dash, unit)
    await signIn(page)
    await openUnit(page, unit)

    const stopped = page.getByRole('status', { name: 'Generation stopped' })
    await expect(stopped).toContainText('Stopped: spend cap reached')
    await expect(stopped).toContainText(
      `23 of 41 lessons were generated before the run reached its ${usd(STOPPED_RUN.capUsd)} cap. No new jobs were started; 17 lessons were not generated and 1 failed. Finished lessons are kept and can be edited.`,
    )
    await expect(stopped).toContainText(
      'To finish the unit, an admin raises the cap, then you can resume. Resuming generates only the lessons that are missing.',
    )
    await expect(tile(page, 24, 'Draft')).toBeVisible()
    await expect(tile(page, 25, 'Not generated')).toBeVisible()
    await expect(tile(page, 14, 'Failed')).toBeVisible()
    for (const n of range(25, 41)) {
      await expect(lessonRow(page, n)).toContainText(NOT_STARTED)
    }
    await expect(lessonRow(page, 24)).not.toContainText(NOT_STARTED)
    await expect(termValue(page, 'Running cost')).toHaveText(usd(STOPPED_RUN.costUsd))
    await expect(termValue(page, 'Spend cap')).toHaveText(usd(STOPPED_RUN.capUsd))
    await expect(page.locator('body')).not.toContainText('{{')

    // Only an admin raises the cap; until then Resume stays disabled.
    await expect(page.getByRole('button', { name: 'Resume generation' })).toBeDisabled()
    await expect(page.getByRole('button', { name: 'Raise cap...' })).toHaveCount(0)
    await snap(page, testInfo, 'R12-dashboard-spend-cap')
    await expectNoAxeViolations(page)
  })

  test('an admin raises the run cap within the global SPEND_CAP_USD, then resuming generates only the missing lessons', async ({
    page,
    dash,
  }) => {
    test.setTimeout(150_000)
    const unit = await dash.importSampleUnit()
    const runId = await seedSpendCapState(dash, unit)
    await signIn(page, ADMIN.email)
    await openUnit(page, unit)
    await expect(page.getByRole('button', { name: 'Resume generation' })).toBeDisabled()

    await page.getByRole('button', { name: 'Raise cap...' }).click()
    const dialog = page.getByRole('dialog')
    const field = dialog.getByLabel('Spend cap for this run')
    // The global budget is $20 (SPEND_CAP_USD) and $0.29 of it is spent.
    await expect(dialog).toContainText('$20.00')
    await expect(dialog).toContainText(usd(20 - STOPPED_RUN.costUsd))

    await field.fill('25')
    await dialog.getByRole('button', { name: 'Save cap' }).click()
    await expect(dialog.getByRole('alert')).toBeVisible()
    await expect(field).toHaveAttribute('aria-invalid', 'true')
    expect((await dash.runs(unit.unitId)).find((run) => run.id === runId)!.capUsd).toBe(
      STOPPED_RUN.capUsd,
    )

    await field.fill('1')
    await dialog.getByRole('button', { name: 'Save cap' }).click()
    await expect(dialog).toBeHidden()
    await expect(termValue(page, 'Spend cap')).toHaveText('$1.00')
    expect((await dash.runs(unit.unitId)).find((run) => run.id === runId)!.capUsd).toBe(1)

    const resume = page.getByRole('button', { name: 'Resume generation' })
    await expect(resume).toBeEnabled()
    await resume.click()
    await expect(tile(page, 25, 'Draft')).toBeVisible({ timeout: RUN_MS })
    await expect(tile(page, 41, 'Draft')).toBeVisible({ timeout: RUN_MS })
    await waitForJobs(dash, unit, range(25, 41), 'generated')

    // Finished lessons were not generated again.
    expect(await dash.versionCount(unit, 1)).toBe(1)
    expect((await dash.lessonRow(unit, 1)).content?.body?.title).toBe(seededTitle(1))
  })
})

test.describe('Unit dashboard: regenerate (R11)', () => {
  test('the row menu lists the lesson actions', async ({ page, dash }, testInfo) => {
    const unit = await dash.importSampleUnit()
    await seedReviewState(dash, unit)
    await signIn(page)
    await openUnit(page, unit)

    const more = page.getByRole('button', { name: 'More actions for lesson 12' })
    await expect(more).toHaveAttribute('aria-haspopup', 'menu')
    await more.click()
    const menu = page.getByRole('menu')
    await expect(menu.getByRole('menuitem')).toHaveText([
      'Open in editor',
      'Open lesson view',
      'Assign...',
      'Version history',
      'Regenerate with prompt v1...',
      'Download JSON',
      'Download HTML',
    ])
    await snap(page, testInfo, 'R11-row-actions')
    await page.keyboard.press('Escape')
    await expect(menu).toBeHidden()
    await expect(more).toBeFocused()
  })

  test('regenerating selected lessons names the ones with human edits, then keeps their content as a version', async ({
    page,
    dash,
  }, testInfo) => {
    test.setTimeout(150_000)
    const unit = await dash.importSampleUnit()
    await seedReviewState(dash, unit)
    // Lessons 12 and 15 have human edits (seeded last editors); 18 has none.
    await dash.setLesson(unit, 18, { lastEditorEmail: null })
    const assignee12 = (await dash.lessonRow(unit, 12)).assignee_id
    const versionsBefore = await dash.versionCount(unit, 12)
    await signIn(page)
    await openUnit(page, unit)

    for (const n of [12, 15, 18]) {
      await page.getByRole('checkbox', { name: `Select lesson ${n}`, exact: true }).check()
    }
    const bar = page.getByRole('toolbar', { name: 'Bulk actions' })
    await expect(bar).toContainText('3 lessons selected')
    await bar.getByRole('button', { name: 'Regenerate' }).click()

    const dialog = page.getByRole('alertdialog', { name: 'Regenerate 3 lessons with prompt v1?' })
    await expect(dialog).toContainText(
      'Lessons 12, 15 and 18 will be written again from their outline rows.',
    )
    await expect(dialog).toContainText(
      'Lessons 12 and 15 have human edits. Their current content is saved as a version first, so you can restore it from version history.',
    )
    // The unit has measured lessons now, so the estimate is their average cost (D-024 (2)).
    await expect(dialog).toContainText(
      `Estimated cost ${usd(3 * LESSON_COST_USD)}. Each lesson returns to Draft when it finishes; reviewers keep their assignments.`,
    )
    await expect(dialog.getByRole('button', { name: 'Cancel' })).toBeFocused()
    await snap(page, testInfo, 'R11-regenerate-confirm')

    await dialog.getByRole('button', { name: 'Regenerate 3 lessons' }).click()
    await expect(dialog).toBeHidden()
    await waitForJobs(dash, unit, [12, 15, 18], 'generated')
    await expect
      .poll(async () => (await dash.lessonRow(unit, 12)).content?.body?.title, {
        timeout: RUN_MS,
      })
      .toBe(generatedTitle(12))
    const lesson12 = await dash.lessonRow(unit, 12)
    expect(lesson12.status).toBe('draft')
    expect(lesson12.assignee_id).toBe(assignee12)
    // The edited content was saved first, then the regenerated content.
    expect(await dash.versionCount(unit, 12)).toBeGreaterThanOrEqual(versionsBefore + 2)
    await expect(lessonRow(page, 12).getByRole('link', { name: generatedTitle(12) })).toBeVisible({
      timeout: LIVE_UPDATE_MS,
    })
  })

  test('regenerating one lesson with human edits asks first, and Cancel starts nothing', async ({
    page,
    dash,
  }) => {
    const unit = await dash.importSampleUnit()
    await seedReviewState(dash, unit)
    const runsBefore = (await dash.runs(unit.unitId)).length
    await signIn(page)
    await openUnit(page, unit)

    const more = page.getByRole('button', { name: 'More actions for lesson 15' })
    await more.click()
    await page.getByRole('menuitem', { name: 'Regenerate with prompt v1...' }).click()
    const dialog = page.getByRole('alertdialog', {
      name: /^Regenerate (1 lesson|lesson 15) with prompt v1\?$/,
    })
    await expect(dialog).toContainText(/Lesson 15 ha(s|ve) human edits/)
    await expect(dialog).toContainText(`Estimated cost ${usd(LESSON_COST_USD)}.`)
    await dialog.getByRole('button', { name: 'Cancel' }).click()
    await expect(dialog).toBeHidden()
    expect(await dash.runs(unit.unitId)).toHaveLength(runsBefore)
    expect((await dash.lessonRow(unit, 15)).content?.body?.title).toBe(seededTitle(15))
  })
})
